INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('SC atinge o topo do Ranking de Competitividade dos Estados pela primeira vez', 'Santa Catarina assumiu a 1ª posição no Ranking de Competitividade dos Estados 2026, do Centro de Liderança Pública (CLP), superando São Paulo, que liderava havia 14 edições.', 'Acompanhe os detalhes e desdobramentos sobre santa catarina lidera ranking nacional de competitividade dos estados. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Governança', 'NSC Total', '2026-08-27T15:00:00Z', 'https://www.nsctotal.com.br/economia/sc-atinge-o-topo-do-ranking-de-competitividade-dos-estados-pela-primeira-vez');
INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('Jorginho Mello é reeleito governador de Santa Catarina', 'Jorginho Mello (PL) foi reeleito governador de Santa Catarina já no primeiro turno das eleições de 4 de outubro de 2026, com mais de 50% dos votos válidos.', 'Acompanhe os detalhes e desdobramentos sobre jorginho mello é reeleito governador de sc em primeiro turno. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Governança', 'SBT News', '2026-10-04T22:19:31Z', 'https://sbtnews.sbt.com.br/noticia/eleicoes/jorginho-mello-e-reeleito-governador-de-santa-catarina');
INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('Defesa Civil distribui mais de 56 mil itens após temporais atingirem 109 cidades e deixarem duas mortes em SC', 'A Defesa Civil de SC distribui mais de 56 mil itens (telhas, cumeeiras, cestas básicas, colchões e kits) após temporais que atingem o estado desde 1º de novembro; 5.531 residências foram afetadas.', 'Acompanhe os detalhes e desdobramentos sobre defesa civil envia 56 mil itens de ajuda humanitária a 109 municípios afetados. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Defesa Civil', 'ND Mais', '2026-11-05T15:00:00Z', 'https://ndmais.com.br/tempo/defesa-civil-distribui-mais-de-56-mil-itens-apos-temporais-atingirem-109-cidades-e-deixarem-duas-mortes-em-sc/');
INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('Temporais deixam rastro de destruição em 109 cidades e 32 municípios decretam emergência em SC', 'Balanço de 5 de novembro: 109 municípios com estragos, mais de 5,5 mil residências afetadas, duas mortes e 32 cidades em situação de emergência.', 'Acompanhe os detalhes e desdobramentos sobre trinta e dois municípios de sc decretam situação de emergência após tempestades. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Defesa Civil', 'ND Mais', '2026-11-05T15:00:00Z', 'https://ndmais.com.br/tempo/temporais-deixam-rastro-de-destruicao-em-109-cidades-e-32-municipios-decretam-emergencia-em-sc/');
INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('CBMSC atende mais de 670 ocorrências em 76 municípios catarinenses atingidos por fortes temporais', 'O Corpo de Bombeiros Militar atendeu 671 ocorrências em 76 municípios entre quarta (4) e a madrugada de quinta (5), com os 17 Grupos de Resposta a Desastres em sobreaviso.', 'Acompanhe os detalhes e desdobramentos sobre corpo de bombeiros atende 670 ocorrências durante temporais recentes. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Defesa Civil', 'Folha Metropolitana', '2026-11-05T15:00:00Z', 'https://folhametropolitana.com/cbmsc-atende-mais-de-670-ocorrencias-em-76-municipios-catarinenses-atingidos-por-fortes-temporais/');
INSERT INTO noticias (titulo, resumo, conteudo, categoria, fonte, data_publicacao, url_original) VALUES ('Celesc mobiliza 17 equipes de outras regiões para acelerar recuperação da energia no Oeste de SC', 'A Celesc deslocou 17 equipes de sete regionais para o Oeste, onde o pico chegou a mais de 247 mil unidades consumidoras sem energia na quarta-feira (4).', 'Acompanhe os detalhes e desdobramentos sobre celesc mobiliza 17 equipes de emergência para restabelecer energia no oeste. A medida e acoes foram registradas nos orgaos oficiais de Santa Catarina.', 'Defesa Civil', 'NoPonto SC', '2026-11-05T15:00:00Z', 'https://nopontosc.com.br/2026/11/05/celesc-mobiliza-17-equipes-de-outras-regioes-para-acelerar-recuperacao-da-energia-no-oeste-de-sc/');
